// TestNumericFormatJS compares key-extraction number formatting against
// JS String(number) for boundary magnitudes (fixture generated by node).
func TestNumericFormatJS(t *testing.T) {
	data, err := os.ReadFile("testdata/gen/numeric_format.json")
	if err != nil {
		t.Fatal(err)
	}
	var jsStrings []string
	if err := json.Unmarshal(data, &jsStrings); err != nil {
		t.Fatal(err)
	}
	if len(jsStrings) < 15 {
		t.Fatalf("fixture too small: %d entries", len(jsStrings))
	}
	for _, js := range jsStrings {
		f, err := strconv.ParseFloat(js, 64)
		if err != nil {
			t.Fatalf("parse %q: %v", js, err)
		}
		if got := jsFormatFloat(f); got != js {
			t.Errorf("jsFormatFloat(%v) = %q, JS String = %q", f, got, js)
		}
	}
}

// interchangeFixture mirrors testdata/index_from_js.json (built by gen.js).
type interchangeFixture struct {
	Docs    []any           `json:"docs"`
	Keys    []any           `json:"keys"`
	Options map[string]any  `json:"options"`
	Index   json.RawMessage `json:"index"`
	Results []struct {
		ID      string `json:"id"`
		Query   string `json:"query"`
		Results []any  `json:"results"`
	} `json:"results"`
}

func loadInterchange(t *testing.T) interchangeFixture {
	t.Helper()
	data, err := os.ReadFile("testdata/index_from_js.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx interchangeFixture
	if err := json.Unmarshal(data, &fx); err != nil {
		t.Fatal(err)
	}
	return fx
}

// TestInterchangeJStoGo parses an index serialized by fuse.js (toJSON) and
// must reproduce, bit-exact, the search results fuse.js produced when
// searching through its own parseIndex of the same JSON.
func TestInterchangeJStoGo(t *testing.T) {
	fx := loadInterchange(t)
	opts := buildOptions(fx.Options)
	ix, err := ParseIndex(fx.Index, &IndexOptions{FieldNormWeight: opts.FieldNormWeight})
	if err != nil {
		t.Fatalf("ParseIndex(JS json): %v", err)
	}
	f, err := New(fx.Docs, opts, ix)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	for _, c := range fx.Results {
		res, err := f.Search(c.Query, nil)
		if err != nil {
			t.Fatalf("%s: Search(%q): %v", c.ID, c.Query, err)
		}
		got := resultsToGeneric(res, true, true)
		compareResults(t, c.ID+" "+c.Query, c.Results, got)
	}
}

// TestInterchangeGotoJS marshals a Go-built index and requires it to be
// byte-identical (semantically) to the index fuse.js built over the same
// docs and keys - so a JS consumer's parseIndex accepts it unchanged.
// testdata/gen/verify_index_from_go.mjs additionally loads it in node.
func TestInterchangeGotoJS(t *testing.T) {
	fx := loadInterchange(t)
	opts := buildOptions(fx.Options)
	ix, err := CreateIndex(buildKeys(fx.Keys), fx.Docs, &IndexOptions{FieldNormWeight: opts.FieldNormWeight})
	if err != nil {
		t.Fatalf("CreateIndex: %v", err)
	}
	goJSON, err := ix.MarshalIndex()
	if err != nil {
		t.Fatalf("MarshalIndex: %v", err)
	}
	var goSide, jsSide any
	if err := json.Unmarshal(goJSON, &goSide); err != nil {
		t.Fatalf("go index JSON invalid: %v", err)
	}
	if err := json.Unmarshal(fx.Index, &jsSide); err != nil {
		t.Fatalf("js index JSON invalid: %v", err)
	}
	if !reflect.DeepEqual(normalizeJSON(goSide), normalizeJSON(jsSide)) {
		// Show a compact diff hint.
		gb, _ := json.Marshal(goSide)
		jb, _ := json.Marshal(jsSide)
		n := len(gb)
		if len(jb) < n {
			n = len(jb)
		}
		i := 0
		for i < n && gb[i] == jb[i] {
			i++
		}
		lo := i - 60
		if lo < 0 {
			lo = 0
		}
		t.Fatalf("Go-marshaled index differs from fuse.js index at byte %d:\n go: ...%s\n js: ...%s",
			i, gb[lo:min(i+120, len(gb))], jb[lo:min(i+120, len(jb))])
	}
}

// normalizeJSON canonicalizes decoded JSON for comparison (map key order is
// already irrelevant to DeepEqual; numbers unify to float64 on both sides).
func normalizeJSON(v any) any { return v }

// TestExtendedEdgeGoldens pins empty-capture extended-search patterns
// (fuse.js `if (token)` truthiness) against node-generated expectations.
func TestExtendedEdgeGoldens(t *testing.T) {
	data, err := os.ReadFile("testdata/extended_edge.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx struct {
		Docs    []any          `json:"docs"`
		Options map[string]any `json:"options"`
		Cases   []struct {
			ID       string `json:"id"`
			Query    string `json:"query"`
			Expected []any  `json:"expected"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(data, &fx); err != nil {
		t.Fatal(err)
	}
	opts := buildOptions(fx.Options)
	f, err := New(fx.Docs, opts, nil)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	for _, c := range fx.Cases {
		res, err := f.Search(c.Query, nil)
		if err != nil {
			t.Fatalf("%s: Search(%q): %v", c.ID, c.Query, err)
		}
		got := resultsToGeneric(res, true, true)
		compareResults(t, c.ID+" "+strconv.Quote(c.Query), c.Expected, got)
	}
}

var _ = bytes.Equal
